const express = require('express');
const { Pool } = require('pg');
const crypto = require('crypto');
const argon2 = require('argon2');

const app = express();
app.use(express.json());

const pool = new Pool({
  host: process.env.DB_HOST || '127.0.0.1',
  port: parseInt(process.env.DB_PORT || '5432'),
  database: process.env.DB_NAME || 'appdb',
  user: process.env.DB_USER || 'appuser',
  password: process.env.DB_PASS,
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: true } : false,
  max: 20
});

if (!process.env.DB_PASS) {
  console.error('DB_PASS environment variable required');
  process.exit(1);
}

const SESSION_SECRET = process.env.SESSION_SECRET;
if (!SESSION_SECRET || SESSION_SECRET.length < 32) {
  console.error('SESSION_SECRET must be at least 32 characters');
  process.exit(1);
}

const sessions = new Map();

function generateToken(userId) {
  const sessionId = crypto.randomBytes(32).toString('hex');
  const token = crypto.createHmac('sha256', SESSION_SECRET)
    .update(sessionId + ':' + userId)
    .digest('hex');
  sessions.set(token, { userId, createdAt: Date.now(), expiresAt: Date.now() + 3600000 });
  return token;
}

function authenticate(req, res, next) {
  const token = req.headers['x-auth-token'];
  if (!token || typeof token !== 'string' || token.length !== 64) {
    return res.status(401).json({ error: 'Authentication required' });
  }
  const session = sessions.get(token);
  if (!session || session.expiresAt < Date.now()) {
    sessions.delete(token);
    return res.status(401).json({ error: 'Session expired' });
  }
  req.userId = session.userId;
  next();
}

// Input validation helpers
function isValidUUID(str) {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(str);
}

function isValidUsername(str) {
  return typeof str === 'string' && /^[a-zA-Z0-9_]{3,30}$/.test(str);
}

function isValidEmail(str) {
  return typeof str === 'string' && /^[^@\s]{1,64}@[^@\s]{1,255}$/.test(str) && str.length <= 320;
}

function sanitizeOrderBy(field, allowed) {
  return allowed.includes(field) ? field : allowed[0];
}

function sanitizeDirection(dir) {
  return dir === 'DESC' ? 'DESC' : 'ASC';
}

// Registration
app.post('/api/register', async (req, res) => {
  try {
    const { username, password, email } = req.body;
    if (!isValidUsername(username)) return res.status(400).json({ error: 'Invalid username' });
    if (!password || typeof password !== 'string' || password.length < 8 || password.length > 128) {
      return res.status(400).json({ error: 'Invalid password' });
    }
    if (!isValidEmail(email)) return res.status(400).json({ error: 'Invalid email' });

    const existing = await pool.query('SELECT id FROM users WHERE username = $1', [username]);
    if (existing.rows.length > 0) return res.status(409).json({ error: 'Username taken' });

    const hash = await argon2.hash(password, { type: argon2.argon2id, memoryCost: 65536, timeCost: 3 });
    const id = crypto.randomUUID();
    await pool.query(
      'INSERT INTO users (id, username, email, password_hash, role) VALUES ($1, $2, $3, $4, $5)',
      [id, username, email, hash, 'user']
    );
    res.status(201).json({ id, username });
  } catch (err) {
    if (err.code === '23505') return res.status(409).json({ error: 'Username taken' });
    console.error('Registration error:', err.message);
    res.status(500).json({ error: 'Internal error' });
  }
});

// Login
app.post('/api/login', async (req, res) => {
  try {
    const { username, password } = req.body;
    if (!isValidUsername(username) || !password || typeof password !== 'string') {
      return res.status(400).json({ error: 'Invalid credentials' });
    }
    const result = await pool.query('SELECT id, password_hash, role FROM users WHERE username = $1', [username]);
    if (result.rows.length === 0) {
      await argon2.hash('dummy-password-for-timing', { type: argon2.argon2id, memoryCost: 65536, timeCost: 3 });
      return res.status(401).json({ error: 'Invalid credentials' });
    }
    const user = result.rows[0];
    const valid = await argon2.verify(user.password_hash, password);
    if (!valid) return res.status(401).json({ error: 'Invalid credentials' });

    const token = generateToken(user.id);
    res.json({ token, userId: user.id, role: user.role });
  } catch (err) {
    console.error('Login error:', err.message);
    res.status(500).json({ error: 'Internal error' });
  }
});

// Search documents with filters
app.get('/api/documents/search', authenticate, async (req, res) => {
  try {
    const { tags, status, sortBy, sortDir, page } = req.query;

    // Validate and parse tags
    let tagList = [];
    if (tags) {
      tagList = String(tags).split(',').map(t => t.trim()).filter(t => /^[a-zA-Z0-9_-]{1,50}$/.test(t));
      if (tagList.length === 0 || tagList.length > 20) {
        return res.status(400).json({ error: 'Invalid tags parameter' });
      }
    }

    // Validate status
    const validStatuses = ['draft', 'published', 'archived'];
    const docStatus = validStatuses.includes(status) ? status : null;

    // Validate sorting
    const orderField = sanitizeOrderBy(sortBy, ['created_at', 'updated_at', 'title']);
    const orderDir = sanitizeDirection(String(sortDir).toUpperCase());

    // Validate pagination
    const pageNum = Math.max(1, Math.min(1000, parseInt(page) || 1));
    const pageSize = 20;
    const offset = (pageNum - 1) * pageSize;

    // Build query with parameterized inputs
    let paramIndex = 1;
    const params = [req.userId];
    let whereClause = `WHERE (d.owner_id = $${paramIndex} OR d.id IN (SELECT document_id FROM document_shares WHERE user_id = $${paramIndex}))`;
    paramIndex++;

    if (docStatus) {
      whereClause += ` AND d.status = $${paramIndex}`;
      params.push(docStatus);
      paramIndex++;
    }

    if (tagList.length > 0) {
      // Build tag filter using ANY with array parameter
      whereClause += ` AND d.id IN (SELECT document_id FROM document_tags WHERE tag = ANY($${paramIndex}))`;
      params.push(tagList);
      paramIndex++;
    }

    const query = `
      SELECT d.id, d.title, d.status, d.created_at, d.updated_at
      FROM documents d
      ${whereClause}
      ORDER BY d.${orderField} ${orderDir}
      LIMIT ${pageSize} OFFSET $${paramIndex}
    `;
    params.push(offset);

    const result = await pool.query(query, params);
    res.json({ documents: result.rows, page: pageNum });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal error' });
  }
});

// Bulk operations on documents
app.post('/api/documents/bulk', authenticate, async (req, res) => {
  try {
    const { action, documentIds, metadata } = req.body;

    // Validate action
    const validActions = ['archive', 'publish', 'tag', 'share'];
    if (!validActions.includes(action)) {
      return res.status(400).json({ error: 'Invalid action' });
    }

    // Validate document IDs
    if (!Array.isArray(documentIds) || documentIds.length === 0 || documentIds.length > 100) {
      return res.status(400).json({ error: 'Invalid document IDs' });
    }
    if (!documentIds.every(id => isValidUUID(id))) {
      return res.status(400).json({ error: 'Invalid document ID format' });
    }

    // Verify ownership of all documents
    const placeholders = documentIds.map((_, i) => `$${i + 2}`).join(',');
    const ownerCheck = await pool.query(
      `SELECT id FROM documents WHERE owner_id = $1 AND id IN (${placeholders})`,
      [req.userId, ...documentIds]
    );

    if (ownerCheck.rows.length !== documentIds.length) {
      return res.status(403).json({ error: 'Access denied to one or more documents' });
    }

    const client = await pool.connect();
    try {
      await client.query('BEGIN');

      if (action === 'archive' || action === 'publish') {
        const newStatus = action === 'archive' ? 'archived' : 'published';
        await client.query(
          `UPDATE documents SET status = $1, updated_at = NOW() WHERE id IN (${placeholders})`,
          [newStatus, ...documentIds]
        );
      } else if (action === 'tag') {
        if (!metadata || !metadata.tag || !/^[a-zA-Z0-9_-]{1,50}$/.test(metadata.tag)) {
          await client.query('ROLLBACK');
          return res.status(400).json({ error: 'Invalid tag' });
        }
        for (const docId of documentIds) {
          await client.query(
            'INSERT INTO document_tags (document_id, tag) VALUES ($1, $2) ON CONFLICT DO NOTHING',
            [docId, metadata.tag]
          );
        }
      } else if (action === 'share') {
        if (!metadata || !isValidUUID(metadata.targetUserId)) {
          await client.query('ROLLBACK');
          return res.status(400).json({ error: 'Invalid target user' });
        }
        for (const docId of documentIds) {
          await client.query(
            'INSERT INTO document_shares (document_id, user_id, permission) VALUES ($1, $2, $3) ON CONFLICT DO NOTHING',
            [docId, metadata.targetUserId, 'read']
          );
        }
      }

      await client.query('COMMIT');
      res.json({ success: true, affected: documentIds.length });
    } catch (txErr) {
      await client.query('ROLLBACK');
      throw txErr;
    } finally {
      client.release();
    }
  } catch (err) {
    console.error('Bulk operation error:', err.message);
    res.status(500).json({ error: 'Internal error' });
  }
});

// Advanced report generation with dynamic filtering
app.post('/api/reports/generate', authenticate, async (req, res) => {
  try {
    const { reportType, filters, groupBy, dateRange } = req.body;

    // Validate report type
    const validReports = ['activity', 'storage', 'sharing'];
    if (!validReports.includes(reportType)) {
      return res.status(400).json({ error: 'Invalid report type' });
    }

    // Validate groupBy
    const validGroupBy = ['day', 'week', 'month'];
    const grouping = validGroupBy.includes(groupBy) ? groupBy : 'day';

    // Validate date range
    const startDate = dateRange?.start ? new Date(dateRange.start) : new Date(Date.now() - 30*24*60*60*1000);
    const endDate = dateRange?.end ? new Date(dateRange.end) : new Date();
    if (isNaN(startDate.getTime()) || isNaN(endDate.getTime())) {
      return res.status(400).json({ error: 'Invalid date range' });
    }

    // Build report query
    let query;
    const params = [req.userId, startDate.toISOString(), endDate.toISOString()];

    if (reportType === 'activity') {
      // Validate optional status filter
      let statusFilter = '';
      if (filters?.status && ['draft', 'published', 'archived'].includes(filters.status)) {
        statusFilter = ` AND d.status = $4`;
        params.push(filters.status);
      }

      query = `
        SELECT date_trunc('${grouping}', d.updated_at) as period,
               COUNT(*) as doc_count,
               COUNT(DISTINCT d.status) as status_variety
        FROM documents d
        WHERE d.owner_id = $1
          AND d.updated_at BETWEEN $2 AND $3
          ${statusFilter}
        GROUP BY period
        ORDER BY period DESC
      `;
    } else if (reportType === 'storage') {
      query = `
        SELECT date_trunc('${grouping}', d.created_at) as period,
               COUNT(*) as new_docs,
               SUM(d.size_bytes) as total_bytes
        FROM documents d
        WHERE d.owner_id = $1
          AND d.created_at BETWEEN $2 AND $3
        GROUP BY period
        ORDER BY period DESC
      `;
    } else {
      query = `
        SELECT date_trunc('${grouping}', ds.created_at) as period,
               COUNT(*) as shares_count,
               COUNT(DISTINCT ds.user_id) as unique_recipients
        FROM document_shares ds
        JOIN documents d ON d.id = ds.document_id
        WHERE d.owner_id = $1
          AND ds.created_at BETWEEN $2 AND $3
        GROUP BY period
        ORDER BY period DESC
      `;
    }

    const result = await pool.query(query, params);
    res.json({ report: reportType, groupBy: grouping, data: result.rows });
  } catch (err) {
    console.error('Report error:', err.message);
    res.status(500).json({ error: 'Internal error' });
  }
});

// Export documents with format selection
app.get('/api/documents/:id/export', authenticate, async (req, res) => {
  try {
    const { id } = req.params;
    const { format } = req.query;

    if (!isValidUUID(id)) return res.status(400).json({ error: 'Invalid document ID' });

    const validFormats = ['json', 'csv', 'xml'];
    if (!validFormats.includes(format)) {
      return res.status(400).json({ error: 'Invalid format. Use: json, csv, xml' });
    }

    // Check access
    const doc = await pool.query(
      `SELECT d.* FROM documents d
       LEFT JOIN document_shares ds ON ds.document_id = d.id AND ds.user_id = $2
       WHERE d.id = $1 AND (d.owner_id = $2 OR ds.user_id IS NOT NULL)`,
      [id, req.userId]
    );
    if (doc.rows.length === 0) return res.status(404).json({ error: 'Document not found' });

    const document = doc.rows[0];

    if (format === 'json') {
      res.json(document);
    } else if (format === 'csv') {
      const headers = Object.keys(document).join(',');
      const values = Object.values(document).map(v => `"${String(v).replace(/"/g, '""')}"`).join(',');
      res.setHeader('Content-Type', 'text/csv');
      res.send(`${headers}\n${values}`);
    } else {
      // XML export
      let xml = '<?xml version="1.0" encoding="UTF-8"?>\n<document>\n';
      for (const [key, value] of Object.entries(document)) {
        xml += `  <${key}>${String(value).replace(/[<>&]/g, c => ({'<':'&lt;','>':'&gt;','&':'&amp;'}[c]))}</${key}>\n`;
      }
      xml += '</document>';
      res.setHeader('Content-Type', 'application/xml');
      res.send(xml);
    }
  } catch (err) {
    console.error('Export error:', err.message);
    res.status(500).json({ error: 'Internal error' });
  }
});

